import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFredoka = makeLoadFont('Fredoka');

// Load playful, rounded font matching the vibe of the reference
const { fontFamily: fredokaFamily } = loadFredoka();



export type RouletteGameProps = Record<string, any>;

const RouletteGame: React.FC<RouletteGameProps> = ({
  backgroundColor = "#e8f8e8",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "Pause the video to see who always makes mistakes in a relationship",
  titleColor = "#000000",
  option1Text = "Him",
  option2Text = "Her",
  option1Color = "#4fc3f7",
  option2Color = "#f06292",
  pointerColor = "#ffb74d",
  pointerAccentColor = "#f57c00",
  spinSpeedMultiplier = 35, // Fast spin by default
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const centerX = width / 2;
  const centerY = height * 0.55; // Slightly lower than center to leave room for title
  const radius = width * 0.32; // Radius for the circular options

  // Title entrance animation
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [0, 15], [-50, 0], { extrapolateRight: "clamp" });

  // Pointer Entrance animation
  const pointerScale = spring({
    frame: frame - 20,
    fps,
    config: { damping: 12, stiffness: 150 },
  });

  // Continuous Fast Rotation
  // We start the rotation slightly after the pointer scales in, but continuous
  const rotationOffset = interpolate(frame, [0, 20], [0, 0], { extrapolateRight: "clamp" }); // Keep static for first 20 frames
  const activeRotationFrames = Math.max(0, frame - 20);
  const pointerRotation = (activeRotationFrames * spinSpeedMultiplier) % 360;

  // Generate the 8 options around the circle
  const numItems = 8;
  const options = Array.from({ length: numItems }).map((_, i) => {
    // Start from top (-90 degrees) and go clockwise
    const angle = (i * (Math.PI * 2)) / numItems - Math.PI / 2;
    
    // Stagger entrance based on index
    const delay = 5 + i * 2;
    const itemScale = spring({
      frame: frame - delay,
      fps,
      config: { damping: 10, stiffness: 120 },
    });

    return {
      id: i,
      text: i % 2 === 0 ? option1Text : option2Text,
      color: i % 2 === 0 ? option1Color : option2Color,
      x: Math.cos(angle) * radius,
      y: Math.sin(angle) * radius,
      scale: itemScale,
    };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: fredokaFamily, overflow: "hidden" }}>
      
      {/* Title Section */}
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: "50%",
          transform: `translate(-50%, ${titleY}px)`,
          width: "80%",
          textAlign: "center",
          opacity: titleOpacity,
          color: titleColor,
          fontSize: width * 0.065,
          fontWeight: 600,
          lineHeight: 1.2,
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* Circular Options Map */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: centerY,
          transition: "none",
        }}
      >
        {options.map((opt) => (
          <div
            key={opt.id}
            style={{
              position: "absolute",
              left: opt.x,
              top: opt.y,
              transform: `translate(-50%, -50%) scale(${opt.scale})`,
              color: opt.color,
              fontSize: width * 0.055,
              fontWeight: 700,
              textShadow: "2px 2px 0px rgba(0,0,0,0.05)",
              transition: "none",
            }}
          >
            {opt.text}
          </div>
        ))}

        {/* The "Hole" base */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: width * 0.15,
            width: width * 0.45,
            height: width * 0.1,
            backgroundColor: "#000000",
            borderRadius: "50%",
            transform: `translate(-50%, -50%) scale(${pointerScale})`,
            transition: "none",
          }}
        />

        {/* The Spinning Pointer */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            // Rotate around the visual center of the circle, but the arrow sits above it
            transform: `translate(-50%, -50%) scale(${pointerScale}) rotate(${pointerRotation}deg)`,
            transformOrigin: "center center",
            width: width * 0.4,
            height: width * 0.4,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          {/* Custom SVG Arrow pointing roughly towards the edge */}
          {/* We offset it upwards inside its bounding box so it spins around the center but points out */}
          <svg
            width="100%"
            height="100%"
            viewBox="0 0 200 200"
            style={{ overflow: "visible", transition: "none" }}
          >
            {/* The Arrow Shape */}
            <g transform="translate(100, 100)">
              {/* Shift the drawing up so its base is at 0,0 and it points to -Y */}
              <polygon
                points="0,-120 40,-40 15,-40 15,20 -15,20 -15,-40 -40,-40"
                fill={pointerColor}
                stroke="#000000"
                strokeWidth="6"
                strokeLinejoin="round"
                strokeLinecap="round"
              />
              {/* Highlight/Accent on the arrow for depth */}
              <polygon
                points="0,-105 25,-45 10,-45 10,10 -10,10 -10,-45 -25,-45"
                fill={pointerAccentColor}
                opacity={0.6}
              />
              {/* Center Pivot Point (visual anchor) */}
              <circle cx="0" cy="0" r="15" fill="#ffffff" stroke="#000000" strokeWidth="6" />
              <circle cx="0" cy="0" r="5" fill="#000000" />
            </g>
          </svg>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default RouletteGame;